const TOOLS = [
  {
    name: 'text_transform',
    description: 'Transform text: uppercase, lowercase, or URL slug.',
    inputSchema: {
      type: 'object',
      properties: {
        text: { type: 'string', description: 'Input text to transform.' },
        mode: {
          type: 'string',
          enum: ['uppercase', 'lowercase', 'slug'],
          description: 'Transformation mode.',
        },
        trim: { type: 'boolean', description: 'Trim whitespace before transforming (default true).' },
      },
      required: ['text', 'mode'],
      additionalProperties: false,
    },
  },
];

const ALLOWED_MODES = new Set(['uppercase', 'lowercase', 'slug']);
const ALLOWED_KEYS = new Set(['text', 'mode', 'trim']);

function slugify(input) {
  const lowered = input.toLowerCase();
  const hyphenated = lowered.replace(/[^a-z0-9]+/g, '-');
  return hyphenated.replace(/^-+|-+$/g, '');
}

export async function listTools() {
  return TOOLS;
}

export async function callTool(name, args) {
  if (name !== 'text_transform') {
    throw new Error('Unknown tool: ' + name);
  }

  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('arguments must be an object');
  }

  for (const key of Object.keys(args)) {
    if (!ALLOWED_KEYS.has(key)) {
      throw new Error('Unexpected argument: ' + key);
    }
  }

  const { text, mode } = args;

  if (typeof text !== 'string') {
    throw new Error('text must be a string');
  }
  if (!ALLOWED_MODES.has(mode)) {
    throw new Error('mode must be one of: uppercase, lowercase, slug');
  }

  const trim = args.trim === undefined ? true : args.trim;
  if (typeof trim !== 'boolean') {
    throw new Error('trim must be a boolean');
  }

  let value = trim ? text.trim() : text;
  if (mode === 'uppercase') {
    value = value.toUpperCase();
  } else if (mode === 'lowercase') {
    value = value.toLowerCase();
  } else {
    value = slugify(value);
  }

  return { content: [{ type: 'text', text: value }] };
}

